/**
  @file
  @brief A program to try in the demo

  Press Run in Studio. This host has no SAS binary, so the site answers with a
  recorded session of this program - the log, the two-page listing and the webout
  are that session's output, with the "Licensed to ..., Site ..." line removed.
  Any other .sas program is refused: the recording names this one, and a demo
  that invented a session for every program would be teaching the wrong thing.
**/

libname demo "/sasjs/drive/files/Public/demo";
options fmterr nodsnferr;

data demo.orders;
set demo.orders_raw;
where order_date >= '01JAN2026'd;
amount_gbp = amount * fx_rate;
if missing(fx_rate) then amount_gbp = 0;
run;
data demo.orders2;
infile datalines dsd truncover;
input order_id $ order_date :date9. amount :comma.;
datalines;
A-10418,15JAN2026,"1,284.50"
A-10419,15JAN2026,902.10
A-10420,32JAN2026,741.25
A-10421,16JAN2026,"2,210.00"
A-10422,17JAN2026,N/A
;
proc print data=demo.orders(obs=5);
var order_id order_date customer amount_gbp;
run;
proc sort data=demo.orders out=demo.orders_sorted;
by customer amount_gbp;
run;
proc sql;
create table demo.totals as
select customer, sum(amount_gbp) as total_gbp
from demo.orders
group by customer;
data demo.merged;
merge demo.orders(in=a) demo.orders2(in=b);
by order_id;
if a and b then matched = 1;
else matched = 0;
run;
data demo.flagged;
set demo.totals;
if total_gbp > 10000 then flag = 'HIGH';
else if total_gbp > &threshold then flag = 'MEDIUM';
else flag = 'LOW';
run;
data demo.bad;
set demo.orders;
net = amount_gbp - refund_amt;
run;
proc means data=demo.orders mean min max;
var amount_gbp;
proc print data=demo.totals(obs=3);
run;

files./sasjs/drive/files/home/sasjsadmin/run.j:
/**
  @file
  @brief A program that DOES run in this browser

  Press Run in Studio: the service worker executes this file, the same way
  sasjs/server would execute it, and the log and webout appear in their tabs.
**/

const rows = [
  { name: 'Alice', age: 14 },
  { name: 'Bob', age: 15 },
  { name: 'Carol', age: 13 }
]

console.log(`Read ${rows.length} rows`)

// The three calls a JS stored program makes on sasjs/server, in the order it
// makes them: OPEN starts the body, OBJ writes a table keyed by column name,
// CLOSE adds the system block and closes the object. webout() is not a
// data sink - a bare array is refused, here and on the server, because the two
// hosts generate the same block.
webout('OPEN')
webout('OBJ', 'adults', rows.filter((row) => row.age > 13))
webout('CLOSE')

files./sasjs/drive/files/Public/app/macrodash/:
body {
  background: #0b1f3a;
  color: #dbe7ff;
  font-family: monospace;
  text-align: center;
  margin: 0;
  padding: 1em;
}

/* clickable brand header: logo + gradient title + tagline */
#brand {
  /* block-level (not inline-flex): an inline box shares a line with the
     inline-block #game canvas, and baseline alignment sinks the brand to the
     canvas bottom on wide viewports */
  display: flex;
  width: fit-content;
  margin: 0 auto;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  text-decoration: none;
  cursor: pointer;
  padding: 4px 10px;
  border-radius: 12px;
  transition: background 0.15s;
}

#brand:hover {
  background: #122a4d;
}

#brand img {
  image-rendering: pixelated;
  border-radius: 6px;
}

#brand .brandtext {
  display: flex;
  flex-direction: column;
  align-items: center;
}

h1 {
  margin: 0;
  font-size: 1.9em;
  letter-spacing: 0.18em;
  background: linear-gradient(90deg, #7fc4ff 0%, #4da3ff 45%, #7C4DFF 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.tagline {
  color: #8aa8d8;
  font-size: 0.75em;
  letter-spacing: 0.3em;
  text-transform: uppercase;
}

#game {
  display: inline-block;
  border: 4px solid #4da3ff;
  background: #000;
}

canvas {
  display: block;
  image-rendering: pixelated;
  max-width: 100%;
  height: auto;
}

#game {
  max-width: 100%;
}

sasjs {
  display: none;
}

/* ---- on-screen controls: RUN left, arrows right ---- */
#pad {
  width: 808px; /* matches #game (800px canvas + 2x4px border) */
  max-width: 100%;
  margin: 16px auto 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 10px;
  box-sizing: border-box;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}

.padbtn {
  font-family: monospace;
  font-weight: bold;
  color: #dbe7ff;
  background: #1a3a66;
  border: 3px solid #4da3ff;
  border-radius: 14px;
  cursor: pointer;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.padbtn.held {
  background: #4da3ff;
  color: #061224;
}

/* big round RUN button, left thumb */
.runbtn {
  width: 92px;
  height: 92px;
  border-radius: 50%;
  flex-direction: column;
  gap: 2px;
}

.runbtn .runlbl {
  font-size: 12px;
  letter-spacing: 0.2em;
}

/* arrow cluster, right thumb: up above left/right */
.arrows {
  display: grid;
  grid-template-areas:
    ". up ."
    "left . right";
  gap: 10px;
}

.abtn {
  width: 68px;
  height: 68px;
  font-size: 22px;
}

.abtn.up    { grid-area: up; }
.abtn.left  { grid-area: left; }
.abtn.right { grid-area: right; }

/* bigger targets on touch devices */
@media (pointer: coarse) {
  .runbtn { width: 104px; height: 104px; }
  .abtn { width: 78px; height: 78px; font-size: 26px; }
}

.hint {
  color: #8aa8d8;
  font-size: 0.9em;
}

#credits {
  color: #b8cdee;
  font-size: 0.85em;
  margin-top: 1em;
}

#credits a {
  color: #ffd54d;
  text-decoration: none;
}

#credits a:hover {
  text-decoration: underline;
}

#credits .sep {
  margin: 0 0.6em;
}

